import{_ as t,o as a,c as i,ai as r}from"./chunks/framework.Ci0kozOl.js";const u=JSON.parse('{"title":"UnoPim Frontend Overview","description":"","frontmatter":{},"headers":[],"relativePath":"0.3/architecture/frontend.md","filePath":"0.3/architecture/frontend.md","lastUpdated":1786019473000}'),n={name:"0.3/architecture/frontend.md"};function o(s,e,l,d,c,f){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="unopim-frontend-overview" tabindex="-1">UnoPim Frontend Overview <a class="header-anchor" href="#unopim-frontend-overview" aria-label="Permalink to &quot;UnoPim Frontend Overview&quot;">​</a></h1><p>UnoPim&#39;s frontend uses modern tools and frameworks to create a responsive and dynamic user interface.</p><h2 id="tailwind-css" tabindex="-1">Tailwind CSS <a class="header-anchor" href="#tailwind-css" aria-label="Permalink to &quot;Tailwind CSS&quot;">​</a></h2><p>UnoPim uses <a href="https://tailwindcss.com/" target="_blank" rel="noreferrer">Tailwind CSS</a>, a customizable utility-first CSS framework for building responsive designs quickly.</p><ul><li><strong>Customization</strong>: Tailwind CSS offers flexible configuration to suit different project needs.</li><li><strong>Utility-First Approach</strong>: It provides utility classes for efficient design within HTML.</li></ul><p>To set up Tailwind CSS, define your Blade file path and the JavaScript directory in the <code>tailwind.config.js</code> file. Tailwind will compile the CSS from the defined location.</p><h2 id="vue-js" tabindex="-1">Vue.js <a class="header-anchor" href="#vue-js" aria-label="Permalink to &quot;Vue.js&quot;">​</a></h2><p>UnoPim’s dynamic UI is powered by <a href="https://vuejs.org/" target="_blank" rel="noreferrer">Vue.js</a>, a flexible JavaScript framework.</p><ul><li><strong>Reactive Components</strong>: Vue.js allows for real-time updates as data changes.</li><li><strong>Component-Based Architecture</strong>: Vue.js promotes reusable and maintainable components.</li></ul><p>UnoPim uses <a href="https://vitejs.dev/" target="_blank" rel="noreferrer">Vite</a> as a build tool, offering a faster development experience. The <code>vite.config.js</code> file defines the build paths, and Vite compiles CSS and JavaScript into the public directory.</p><h2 id="blade" tabindex="-1">Blade <a class="header-anchor" href="#blade" aria-label="Permalink to &quot;Blade&quot;">​</a></h2><p>UnoPim leverages the Blade template engine, integrated with <a href="https://laravel.com" target="_blank" rel="noreferrer">Laravel</a>, for creating flexible and dynamic templates.</p><ul><li><strong>Template Inheritance</strong>: Blade allows a modular structure through template inheritance.</li><li><strong>Directives</strong>: Blade simplifies common tasks like loops and conditionals with its built-in directives.</li></ul><p>For more details on UnoPim&#39;s directory structure and configuration, visit the <a href="https://devdocs.unopim.com/0.1/packages/views.html#directory-structure" target="_blank" rel="noreferrer">official documentation</a>.</p>',14)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
